// Generated by scripts/sync-draw-blocks.mjs from Draw. Edit the production source, then sync.
// Building blocks. General holds vendor-neutral components and the Learn
// designer's general blocks and dependencies; uug.ai holds our products. Those
// from the designer (learn/app/assets/js/designer.js) keep its keys and node
// colours (rete-diagram.css), so boards and designer diagrams speak the same
// language. Then cloud services, Kubernetes, and isometric icons drawn with
// the design system's code.

import { isoIcons } from './isoIcons'
import type { IsoIcon } from './isoIcons'
import type { Shape } from './types'

export interface BlockType {
  key: string
  header: string
  title: string
  subtitle: string
  /** The header colour. */
  color: string
  /** The size a new block starts at. */
  w: number
  h: number
  /** Platform icons from public/badges. */
  badges?: string[]
  /** Name in the palette, when it differs from the title. */
  label?: string
  /** An image above the title, such as a cloud provider's official service icon. */
  logo?: string
  /** Drawn as this isometric icon instead of a card. */
  icon?: IsoIcon
}

/** Board pixels per isometric unit, so every icon is drawn at one scale. */
const isoScale = 2.4

const isoBlock = (key: string, name: keyof typeof isoIcons): BlockType => {
  const icon = isoIcons[name]
  const [, , w, h] = icon.viewBox.split(' ').map(Number)
  return {
    key,
    header: '',
    title: icon.title,
    subtitle: '',
    color: '#7426ff',
    w: Math.round(w * isoScale),
    h: Math.round(h * isoScale),
    icon,
  }
}

export interface BlockSection {
  title: string
  /** A group the section is listed under, such as our own products under uug.ai. */
  group?: string
  blocks: BlockType[]
}

