const byKey = new Map(blockSections.flatMap((section) => section.blocks.map((b) => [b.key, b])))

// Kinds Learn diagrams use outside the palette that have a colour of their own.
const otherColors: Record<string, string> = { detection: '#047857' }

/** The block type for a key; unknown keys, say from a newer app, draw as a generic node. */
export function blockType(key: string | undefined): BlockType {
  return (
    byKey.get(key ?? '') ?? {
      key: key ?? 'default',
      header: 'NODE',
      title: key ?? 'Node',
      subtitle: '',
      color: otherColors[key ?? ''] ?? '#6b7280',
      w: 200,
      h: 120,
    }
  )
}

export function isBlockKey(key: string): boolean {
  return byKey.has(key)
}

/** A new block of a type, carrying the type's labels and badges for the shape to own. */
export function newBlock(key: string, id: string, x: number, y: number): Shape {
  const type = blockType(key)
  const labels = type.icon
    ? {}
    : { header: type.header, title: type.title, subtitle: type.subtitle || undefined, badges: type.badges }
  return { id, kind: 'block', block: key, x, y, w: type.w, h: type.h, ...labels, stroke: '#0b0b12', fill: 'none', strokeWidth: 2 }
}

const badgeNames = new Set(['minio', 'ceph', 'aws', 'gcp', 'azure', 'docker', 'linux', 'raspberrypi', 'kubernetes'])

/** Whether public/badges has an icon of this name. */
export function isBadge(name: string): boolean {
  return badgeNames.has(name)
}

/** How small a block can be resized: cards keep their text readable, icons only stay grabbable. */
export function minBlockSize(key: string | undefined): { w: number; h: number } {
  return blockType(key).icon ? { w: 24, h: 24 } : { w: 140, h: 90 }
}

/** The drag-and-drop type that carries a block key from the palette to the board. */
export const blockDragType = 'application/x-collaborate-block'
